WITH base AS (SELECT *, CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END AS is_add_to_cart FROM web_events WHERE event_time >= TO_DATE('2023-10-29') AND event_type = 'add_to_cart'), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM base), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, BIT_OR(duration_sec) AS duration_sec_bit_or, COUNT(CASE WHEN page = '/cart' THEN 1 END) AS cart_count, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, COUNT(*) FILTER (WHERE event_type = 'search') AS search_rows FROM sessionized GROUP BY DATE_TRUNC('WEEK', event_time) HAVING cart_count >= 1 ORDER BY duration_sec_bit_or DESC
